import std.io

pub type AppError = Failed(String)

fn tally(xs: List<Int64>) effect io -> Int64 {
    let s = 0
    for x in xs {
        s = s + x
    }
    return s
}

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3]
    io.println("${tally(xs)}")
    return Ok(())
}
